import java.util.*;

class Solution {
    public List<List<String>> groupByLength(String[] words) {
        Map<Integer, List<String>> groups = new HashMap<>();
        for (String w : words) {
            groups.computeIfAbsent(w.length(), k -> new ArrayList<>()).add(w);
        }
        return new ArrayList<>(groups.values());
    }
}
